# Genera app/exams/hero/<etapa>.json a partir de materiales/hero-tras-sus-pasos/material.html.
# Todas las preguntas salen SOLO de ese material; los pasajes para completar usan únicamente
# los versículos NTV que aparecen ahí, copiados tal cual.  Uso: python3 tools/exams/hero_banks.py
import json, os, re
OUT = os.path.join(os.path.dirname(__file__), '..', '..', 'app', 'exams', 'hero')
B = {}
cur = None
def stage(k):
    global cur; cur = k; B[k] = []
def add(x): x['id'] = '%s-%02d' % (cur[:3], len(B[cur]) + 1); B[cur].append(x)
def M(q, ok, bad, exp, ref=''): add({'t': 'mc', 'q': q, 'o': [ok] + bad, 'a': 0, 'exp': exp, 'ref': ref})
def A(q, ok, bad, exp, ref=''): add({'t': 'app', 'q': q, 'o': [ok] + bad, 'a': 0, 'exp': exp, 'ref': ref})
def T(q, v, exp, ref=''): add({'t': 'tf', 'q': q, 'a': v, 'exp': exp, 'ref': ref})
def P(q, pairs, exp, ref=''): add({'t': 'match', 'q': q, 'p': pairs, 'exp': exp, 'ref': ref})
def O(q, items, exp, ref=''): add({'t': 'order', 'q': q, 'items': items, 'exp': exp, 'ref': ref})
def R(q): add({'t': 'reflect', 'q': q})
def V(text, extra, exp, ref):
    parts, blanks = [], []
    for k, seg in enumerate(re.split(r'\[([^\]]+)\]', text)):
        if k % 2: parts.append(len(blanks)); blanks.append(seg)
        elif seg: parts.append(seg)
    add({'t': 'verse', 'q': 'Completá el versículo', 'parts': parts, 'blanks': blanks, 'bank': blanks + extra, 'exp': exp, 'ref': ref})

